SELECT p.gender, p.age, s.admit_provider_id, s.admission_type_id, s.discharge_disposition_id, s.death_date, s.length_of_stay, s.transfer_time, s.chart_time, s.stay_id, s.hadm_id, s.subject_id, r.composite_risk_score, q.quartile, m.mortality_30d, m.cardiovascular_complications_30d, m.neurologic_complications_30d, m.median_los, m.baseline_mortality_30d FROM patients p JOIN admissions s ON p.subject_id = s.subject_id JOIN risk_scores r ON p.subject_id = r.subject_id JOIN quartiles q ON r.composite_risk_score = q.risk_score JOIN mortality_rates m ON p.gender = m.gender_code AND p.age = m.age_group WHERE p.gender = 'F' AND p.age BETWEEN 59 AND 69 AND s.admission_type_id = 172 AND s.discharge_disposition_id = 372 AND s.death_date IS NOT NULL AND s.length_of_stay <= 30 AND s.transfer_time IS NOT NULL AND s.chart_time IS NOT NULL AND s.stay_id IS NOT NULL AND s.hadm_id IS NOT NULL AND s.subject_id IS NOT NULL ORDER BY q.quartile, m.mortality_30d NULLS LAST;